import React, { useState } from 'react';
import { Skull, Radio, Zap, Repeat, Play, StopCircle, AlertTriangle } from 'lucide-react';
import { SYSTEM_CONSTANTS } from '../utils/constants';

const AttackControl = ({ onLaunchAttack, activeAttacks, onStopAttack, isRunning }) => {
  const [selectedAttack, setSelectedAttack] = useState('MITM');
  const [attackParams, setAttackParams] = useState({
    targetRegister: SYSTEM_CONSTANTS.REGISTERS.TEMPERATURE,
    maliciousValue: 95,
    dangerousValue: 0,
    intensity: 'medium'
  });

  const handleLaunch = () => {
    if (!isRunning) {
      alert('Please start the simulation first');
      return;
    }

    onLaunchAttack(selectedAttack, attackParams);
  };

  const attackTypes = [
    {
      id: 'MITM',
      name: 'Man-in-the-Middle',
      icon: Radio,
      description: 'Intercept and modify Modbus packets in transit',
      color: '#ef4444'
    },
    {
      id: 'DoS',
      name: 'Denial of Service',
      icon: Zap,
      description: 'Flood the network with malformed packets',
      color: '#f59e0b'
    },
    {
      id: 'Injection',
      name: 'Command Injection',
      icon: Skull,
      description: 'Inject unauthorized commands to critical registers',
      color: '#8b5cf6'
    },
    {
      id: 'Replay',
      name: 'Replay Attack',
      icon: Repeat,
      description: 'Capture and replay legitimate commands',
      color: '#3b82f6'
    }
  ];

  const registerOptions = [
    { value: SYSTEM_CONSTANTS.REGISTERS.TEMPERATURE, label: 'Temperature Control' },
    { value: SYSTEM_CONSTANTS.REGISTERS.PRESSURE, label: 'Pressure Control' },
    { value: SYSTEM_CONSTANTS.REGISTERS.FLOW_RATE, label: 'Flow Rate Control' },
    { value: SYSTEM_CONSTANTS.REGISTERS.PUMP_CONTROL, label: 'Pump Control' },
    { value: SYSTEM_CONSTANTS.REGISTERS.VALVE_POSITION, label: 'Valve Position' },
    { value: SYSTEM_CONSTANTS.REGISTERS.SAFETY_INTERLOCK, label: 'Safety Interlock' }
  ];

  return (
    <div className="panel attack-control">
      <div className="panel-header">
        <h2>
          <Skull size={20} />
          Attack Control Center
        </h2>
        <span className="attack-badge">{activeAttacks.length} Active</span>
      </div>

      <div className="attack-selector">
        <label>Select Attack Type:</label>
        <div className="attack-types">
          {attackTypes.map(attack => {
            const Icon = attack.icon;
            return (
              <button
                key={attack.id}
                className={`attack-type-btn ${selectedAttack === attack.id ? 'selected' : ''}`}
                onClick={() => setSelectedAttack(attack.id)}
                style={{ 
                  borderColor: selectedAttack === attack.id ? attack.color : 'transparent',
                  background: selectedAttack === attack.id ? `${attack.color}15` : 'transparent'
                }}
              >
                <Icon size={24} style={{ color: attack.color }} />
                <span>{attack.name}</span>
              </button>
            );
          })}
        </div>
      </div>

      <div className="attack-description">
        <AlertTriangle size={18} />
        <p>{attackTypes.find(a => a.id === selectedAttack)?.description}</p>
      </div>

      <div className="attack-parameters">
        <h3>Attack Parameters</h3>

        {(selectedAttack === 'MITM' || selectedAttack === 'Injection' || selectedAttack === 'Replay') && (
          <div className="param-group">
            <label>Target Register:</label>
            <select 
              value={attackParams.targetRegister}
              onChange={(e) => setAttackParams({
                ...attackParams, 
                targetRegister: parseInt(e.target.value)
              })}
            >
              {registerOptions.map(opt => (
                <option key={opt.value} value={opt.value}>
                  {opt.label} (0x{opt.value.toString(16).toUpperCase().padStart(4, '0')})
                </option>
              ))}
            </select>
          </div>
        )}

        {selectedAttack === 'MITM' && (
          <div className="param-group">
            <label>Malicious Value:</label>
            <input 
              type="number" 
              value={attackParams.maliciousValue}
              onChange={(e) => setAttackParams({
                ...attackParams, 
                maliciousValue: parseInt(e.target.value)
              })}
              min="0"
              max="200"
            />
            <small>Value to inject (0-200)</small>
          </div>
        )}

        {selectedAttack === 'Injection' && (
          <div className="param-group">
            <label>Dangerous Value:</label>
            <input 
              type="number" 
              value={attackParams.dangerousValue}
              onChange={(e) => setAttackParams({
                ...attackParams, 
                dangerousValue: parseInt(e.target.value)
              })}
              min="0"
              max="200"
            />
            <small>Critical value to inject (0-200)</small>
          </div>
        )}

        {(selectedAttack === 'DoS' || selectedAttack === 'MITM') && (
          <div className="param-group">
            <label>Attack Intensity:</label>
            <select 
              value={attackParams.intensity}
              onChange={(e) => setAttackParams({
                ...attackParams, 
                intensity: e.target.value
              })}
            >
              <option value="low">Low (200 pps)</option>
              <option value="medium">Medium (500 pps)</option>
              <option value="high">High (1000 pps)</option>
            </select>
          </div>
        )}
      </div>

      <button 
        className="launch-attack-btn"
        onClick={handleLaunch}
        disabled={!isRunning}
      >
        <Play size={20} />
        Launch {attackTypes.find(a => a.id === selectedAttack)?.name}
      </button>

      {activeAttacks.length > 0 && (
        <div className="active-attacks">
          <h3>Active Attacks</h3>
          <div className="attack-list">
            {activeAttacks.map(attack => (
              <div key={attack.id} className="attack-item">
                <div className="attack-info">
                  <strong>{attack.type}</strong>
                  <span className="attack-duration">
                    {Math.floor((Date.now() - attack.startTime) / 1000)}s
                  </span>
                </div>
                <div className="attack-stats">
                  {attack.packetsModified && <span>{attack.packetsModified} modified</span>}
                  {attack.totalPackets && <span>{attack.totalPackets} packets</span>}
                  {attack.commandsInjected && <span>{attack.commandsInjected} injected</span>}
                  {attack.replaysExecuted && <span>{attack.replaysExecuted} replays</span>}
                </div>
                <button 
                  className="stop-attack-btn"
                  onClick={() => onStopAttack(attack.id)}
                >
                  <StopCircle size={16} />
                  Stop
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="attack-warning">
        <AlertTriangle size={18} />
        <p><strong>Warning:</strong> These attacks can cause critical system failures. Monitor process parameters carefully.</p>
      </div>
    </div>
  );
};

export default AttackControl;
